//! Bounded software RGBA groups. Primitive masks are generated by the same
//! indexed-font/image rasterizer as the opaque path, then sampled through the
//! layout plane's inverse. Intermediate canvases are never opaque white.
use super::DisplayItem;
use crate::display::{ColorProfile, RasterOptions};
use crate::{
    css::values::ResolvedColor,
    layout::{CoordinateSpace, Mat4, Rect, SpatialState},
    media::DecodedImage,
    style::effects::{
        self, Blend, Composite, Effects, Filter, Keyword, MaskImage, MaskMode, MaskSize, Property,
        Repeat, Value,
    },
};
use std::{collections::HashMap, sync::Arc};

#[derive(Clone, Debug, PartialEq)]
pub struct Layer {
    pub effects: Effects,
    pub rect: Rect,
    pub content: Rect,
    pub padding: Rect,
    pub size: f32,
    pub color: ResolvedColor,
    pub spatial: SpatialState,
    pub space: CoordinateSpace,
    pub images: HashMap<String, Arc<DecodedImage>>,
}

const MAX_PIXELS: usize = 4_194_304;
const MAX_GROUP_PIXELS: usize = 33_554_432;
const MAX_BLUR: f32 = 64.0;

fn padding(list: &[DisplayItem], scale: f32) -> usize {
    list.iter()
        .filter_map(|i| {
            if let DisplayItem::BeginLayer(l) = i {
                Some(l)
            } else {
                None
            }
        })
        .map(|l| {
            l.effects
                .filters(Property::Filter)
                .into_iter()
                .chain(l.effects.filters(Property::BackdropFilter))
                .map(|f| match f {
                    Filter::Blur(v) => {
                        (v.resolve(l.size, 0.0).max(0.0) * scale).min(MAX_BLUR) * 3.0
                    }
                    Filter::DropShadow { x, y, blur, .. } => {
                        (blur.resolve(l.size, 0.0).max(0.0) * scale).min(MAX_BLUR) * 3.0
                            + x.resolve(l.size, 0.0)
                                .abs()
                                .max(y.resolve(l.size, 0.0).abs())
                                * scale
                    }
                    _ => 0.0,
                })
                .sum::<f32>()
        })
        .fold(2.0, f32::max)
        .ceil() as usize
}

pub(crate) fn validate(
    list: &[DisplayItem],
    width: usize,
    height: usize,
    scale: f64,
) -> Result<(), String> {
    for item in list {
        let vector = match item {
            DisplayItem::Vector { rect, scene } => Some((*rect, scene)),
            DisplayItem::Image { x, y, w, h, image } => image.vector().map(|scene| {
                (
                    Rect {
                        x: *x,
                        y: *y,
                        width: *w,
                        height: *h,
                    },
                    scene,
                )
            }),
            _ => None,
        };
        if let Some((rect, scene)) = vector {
            let (w, h) = (
                (rect.width * scale as f32).ceil(),
                (rect.height * scale as f32).ceil(),
            );
            if !w.is_finite() || !h.is_finite() || w > 4096.0 || h > 4096.0 {
                return Err("vector device dimensions exceed 4096".into());
            }
            crate::vector::raster::validate(scene, w.max(0.0) as u32, h.max(0.0) as u32)?;
        }
    }
    let active=list.iter().any(|i| matches!(i,DisplayItem::BeginLayer(_)) || matches!(i,DisplayItem::Spatial(s) if s.matrix!=Mat4::translation(s.offset.x as f64,s.offset.y as f64,0.0) || s.hidden));
    if !active {
        return Ok(());
    }
    let pad = padding(list, scale as f32);
    if pad > 384 {
        return Err("effects filter halo exceeds 384 device pixels".into());
    }
    let n = width
        .saturating_add(2 * pad)
        .saturating_mul(height.saturating_add(2 * pad));
    if n > MAX_PIXELS {
        return Err("effects framebuffer exceeds 4,194,304 pixels".into());
    }
    let mut depth = 1usize;
    for item in list {
        match item {
            DisplayItem::BeginLayer(l) => {
                depth += 1;
                if depth * n * 2 > MAX_GROUP_PIXELS {
                    return Err("effects group buffers exceed 128 MiB".into());
                }
                if l.effects.urls().iter().any(|u| !l.images.contains_key(u)) {
                    return Err("mask image is not loaded".into());
                }
            }
            DisplayItem::EndLayer => depth = depth.saturating_sub(1),
            _ => {
                if let Some(r) = item_bounds(item) {
                    let (w, h) = (
                        (r.width * scale as f32).ceil() + 6.0,
                        (r.height * scale as f32).ceil() + 6.0,
                    );
                    if !w.is_finite() || !h.is_finite() || w as f64 * h as f64 > MAX_PIXELS as f64 {
                        return Err("effects primitive texture exceeds 4,194,304 pixels".into());
                    }
                }
            }
        }
    }
    Ok(())
}

fn unpack(p: u32) -> [f32; 4] {
    [
        ((p >> 16) & 255) as f32 / 255.0,
        ((p >> 8) & 255) as f32 / 255.0,
        (p & 255) as f32 / 255.0,
        (p >> 24) as f32 / 255.0,
    ]
}
fn pack(c: [f32; 4]) -> u32 {
    let c = c.map(|v| (v.clamp(0.0, 1.0) * 255.0).round() as u32);
    (c[3] << 24) | (c[0] << 16) | (c[1] << 8) | c[2]
}

fn lum(c: [f32; 3]) -> f32 {
    0.3 * c[0] + 0.59 * c[1] + 0.11 * c[2]
}
fn sat(c: [f32; 3]) -> f32 {
    c.into_iter().fold(0.0, f32::max) - c.into_iter().fold(1.0, f32::min)
}
fn clip_color(mut c: [f32; 3]) -> [f32; 3] {
    let l = lum(c);
    let min = c.into_iter().fold(f32::INFINITY, f32::min);
    let max = c.into_iter().fold(f32::NEG_INFINITY, f32::max);
    if min < 0.0 {
        c = c.map(|v| l + (v - l) * l / (l - min));
    }
    if max > 1.0 {
        c = c.map(|v| l + (v - l) * (1.0 - l) / (max - l));
    }
    c
}
fn set_lum(c: [f32; 3], l: f32) -> [f32; 3] {
    let d = l - lum(c);
    clip_color(c.map(|v| v + d))
}
fn set_sat(c: [f32; 3], s: f32) -> [f32; 3] {
    let mut order = [0, 1, 2];
    order.sort_by(|&a, &b| c[a].total_cmp(&c[b]));
    let [min, mid, max] = order;
    let mut out = [0.0; 3];
    if c[max] > c[min] {
        out[mid] = (c[mid] - c[min]) * s / (c[max] - c[min]);
        out[max] = s;
    }
    out
}

/// W3C Compositing/Blending: straight-sRGB blend function. Alpha composition
/// is separate; transparent backdrop colors cannot leak into the result.
pub fn blend_rgb(b: [f32; 3], s: [f32; 3], mode: Blend) -> [f32; 3] {
    use Blend as B;
    match mode {
        B::Hue => return set_lum(set_sat(s, sat(b)), lum(b)),
        B::Saturation => return set_lum(set_sat(b, sat(s)), lum(b)),
        B::Color => return set_lum(s, lum(b)),
        B::Luminosity => return set_lum(b, lum(s)),
        _ => {}
    }
    std::array::from_fn(|i| {
        let (b, s) = (b[i], s[i]);
        let hard = |b: f32, s: f32| {
            if s <= 0.5 {
                2.0 * b * s
            } else {
                1.0 - 2.0 * (1.0 - b) * (1.0 - s)
            }
        };
        match mode {
            B::Normal => s,
            B::Multiply => b * s,
            B::Screen => b + s - b * s,
            B::Overlay => hard(s, b),
            B::Darken => b.min(s),
            B::Lighten => b.max(s),
            B::ColorDodge => {
                if b == 0.0 {
                    0.0
                } else if s == 1.0 {
                    1.0
                } else {
                    (b / (1.0 - s)).min(1.0)
                }
            }
            B::ColorBurn => {
                if b == 1.0 {
                    1.0
                } else if s == 0.0 {
                    0.0
                } else {
                    1.0 - ((1.0 - b) / s).min(1.0)
                }
            }
            B::HardLight => hard(b, s),
            B::SoftLight => {
                if s <= 0.5 {
                    b - (1.0 - 2.0 * s) * b * (1.0 - b)
                } else {
                    let d = if b <= 0.25 {
                        ((16.0 * b - 12.0) * b + 4.0) * b
                    } else {
                        b.sqrt()
                    };
                    b + (2.0 * s - 1.0) * (d - b)
                }
            }
            B::Difference => (b - s).abs(),
            B::Exclusion => b + s - 2.0 * b * s,
            _ => unreachable!(),
        }
    })
}

pub fn composite(b: u32, s: u32, mode: Blend) -> u32 {
    if mode == Blend::Normal {
        return super::rasterizer::blend(b, s & 0xffffff, s >> 24);
    }
    let (b, s) = (unpack(b), unpack(s));
    let alpha = s[3] + b[3] * (1.0 - s[3]);
    if alpha == 0.0 {
        return 0;
    }
    let blend = blend_rgb([b[0], b[1], b[2]], [s[0], s[1], s[2]], mode);
    pack([
        ((1.0 - s[3]) * b[3] * b[0] + (1.0 - b[3]) * s[3] * s[0] + s[3] * b[3] * blend[0]) / alpha,
        ((1.0 - s[3]) * b[3] * b[1] + (1.0 - b[3]) * s[3] * s[1] + s[3] * b[3] * blend[1]) / alpha,
        ((1.0 - s[3]) * b[3] * b[2] + (1.0 - b[3]) * s[3] * s[2] + s[3] * b[3] * blend[2]) / alpha,
        alpha,
    ])
}

struct Group {
    source: Vec<u32>,
    backdrop: Vec<u32>,
    layer: Option<Layer>,
}
impl Group {
    fn effective(&self, i: usize) -> u32 {
        composite(self.backdrop[i], self.source[i], Blend::Normal)
    }
    fn paint(&mut self, i: usize, s: u32, mode: Blend) {
        let s = if mode == Blend::Normal {
            s
        } else {
            let b = unpack(self.effective(i));
            let s = unpack(s);
            let blended = blend_rgb([b[0], b[1], b[2]], [s[0], s[1], s[2]], mode);
            pack([
                (1.0 - b[3]) * s[0] + b[3] * blended[0],
                (1.0 - b[3]) * s[1] + b[3] * blended[1],
                (1.0 - b[3]) * s[2] + b[3] * blended[2],
                s[3],
            ])
        };
        self.source[i] = composite(self.source[i], s, Blend::Normal);
    }
}

pub(crate) fn rasterize_profile(
    list: &[DisplayItem],
    font: &crate::text::FontContext,
    pixels: &mut [u32],
    width: usize,
    height: usize,
    options: RasterOptions,
) {
    let RasterOptions {
        scale,
        scroll,
        profile,
    } = options;
    if let Err(error) = validate(list, width, height, scale) {
        eprintln!("CSS: {error}; effects render suppressed");
        return;
    }
    let scale = scale as f32;
    if !scale.is_finite()
        || scale <= 0.0
        || width.checked_mul(height).is_none_or(|n| n > pixels.len())
    {
        return;
    }
    let pad = padding(list, scale);
    let (w, h) = (
        width.saturating_add(2 * pad),
        height.saturating_add(2 * pad),
    );
    let Some(n) = w.checked_mul(h).filter(|&n| n <= MAX_PIXELS) else {
        eprintln!("CSS: effects framebuffer exceeds 4,194,304 pixels; render suppressed");
        return;
    };
    let mut stack = vec![Group {
        source: vec![0; n],
        backdrop: vec![0; n],
        layer: None,
    }];
    let mut spatial = SpatialState::default();
    let mut space = CoordinateSpace::Document;
    let mut object = None;
    let mut skipped = 0;
    for item in list {
        match item {
            DisplayItem::BeginLayer(layer) => {
                if skipped > 0 || (stack.len() + 1) * n * 2 > MAX_GROUP_PIXELS {
                    skipped += 1;
                    if skipped == 1 {
                        eprintln!("CSS: effects group memory exceeds 128 MiB; subtree suppressed");
                    }
                    continue;
                }
                let parent = stack.last().unwrap();
                let isolated = layer.effects.keyword(Property::Isolation) == Keyword::Isolate;
                let backdrop = if isolated {
                    vec![0; n]
                } else {
                    (0..n).map(|i| parent.effective(i)).collect()
                };
                let mut group = Group {
                    source: vec![0; n],
                    backdrop,
                    layer: Some((**layer).clone()),
                };
                let filters = layer.effects.filters(Property::BackdropFilter);
                if !filters.is_empty() {
                    let mut captured = (0..n).map(|i| parent.effective(i)).collect::<Vec<_>>();
                    apply_filters_profile(
                        &mut captured,
                        w,
                        h,
                        scale,
                        layer.size,
                        layer.color,
                        &filters,
                        profile,
                    );
                    for y in 0..h {
                        for x in 0..w {
                            let (sx, sy) = (
                                (x as f32 + 0.5 - pad as f32) / scale,
                                (y as f32 + 0.5 - pad as f32) / scale,
                            );
                            let sy = sy
                                + if layer.space == CoordinateSpace::Document {
                                    scroll
                                } else {
                                    0.0
                                };
                            if let Some((u, v)) = layer.spatial.point(sx, sy)
                                && contains(layer.rect, u, v)
                            {
                                group.source[y * w + x] = captured[y * w + x];
                            }
                        }
                    }
                }
                stack.push(group);
            }
            DisplayItem::EndLayer => {
                if skipped > 0 {
                    skipped -= 1;
                    continue;
                }
                if stack.len() == 1 {
                    continue;
                }
                let mut group = stack.pop().unwrap();
                let layer = group.layer.take().unwrap();
                apply_filters_profile(
                    &mut group.source,
                    w,
                    h,
                    scale,
                    layer.size,
                    layer.color,
                    &layer.effects.filters(Property::Filter),
                    profile,
                );
                let parent = stack.last_mut().unwrap();
                let Value::Shape(shape) = layer.effects.get(Property::ClipPath) else {
                    unreachable!()
                };
                let mask = PreparedMask::new(&layer);
                let opacity = layer.effects.number(Property::Opacity);
                let blend = layer.effects.blend();
                for y in 0..h {
                    for x in 0..w {
                        let i = y * w + x;
                        if group.source[i] >> 24 == 0 {
                            continue;
                        }
                        let (sx, sy) = (
                            (x as f32 + 0.5 - pad as f32) / scale,
                            (y as f32 + 0.5 - pad as f32) / scale,
                        );
                        let sy = sy
                            + if layer.space == CoordinateSpace::Document {
                                scroll
                            } else {
                                0.0
                            };
                        let Some((u, v)) = layer.spatial.point(sx, sy) else {
                            continue;
                        };
                        if let Some(shape) = &shape
                            && !shape.contains(layer.rect, layer.size, u, v)
                        {
                            continue;
                        }
                        let alpha = opacity * mask.as_ref().map_or(1.0, |mask| mask.alpha(u, v));
                        let mut s = unpack(group.source[i]);
                        s[3] *= alpha;
                        parent.paint(i, pack(s), blend);
                    }
                }
            }
            _ if skipped > 0 => {}
            DisplayItem::Spatial(s) => spatial = **s,
            DisplayItem::CoordinateSpace(s) => space = *s,
            DisplayItem::ObjectClip(r) => object = Some(*r),
            DisplayItem::ObjectClipEnd => object = None,
            DisplayItem::ViewportBackground { color, .. } => {
                let g = stack.last_mut().unwrap();
                for y in pad..pad + height {
                    for x in pad..pad + width {
                        g.source[y * w + x] = profile.rgb(*color) | 0xff000000;
                    }
                }
            }
            _ => {
                let Some(bounds) = item_bounds(item) else {
                    continue;
                };
                let item_scroll = if space == CoordinateSpace::Document {
                    scroll
                } else {
                    0.0
                };
                let matrix = Mat4::translation(0.0, -item_scroll as f64, 0.0).then(spatial.matrix);
                let Some(visual) = matrix.bounds(bounds) else {
                    continue;
                };
                let origin_x = (bounds.x * scale).floor() / scale - 2.0 / scale;
                let origin_y = (bounds.y * scale).floor() / scale - 2.0 / scale;
                let sw = ((bounds.x + bounds.width - origin_x) * scale)
                    .ceil()
                    .max(0.0) as usize
                    + 2;
                let sh = ((bounds.y + bounds.height - origin_y) * scale)
                    .ceil()
                    .max(0.0) as usize
                    + 2;
                if sw.checked_mul(sh).is_none_or(|n| n > MAX_PIXELS) {
                    continue;
                }
                let mut source = vec![0; sw * sh];
                let state = SpatialState {
                    offset: crate::layout::ScrollOffset {
                        x: -origin_x,
                        y: -origin_y,
                    },
                    ..SpatialState::default()
                };
                super::rasterizer::rasterize_rgba_profile(
                    &[DisplayItem::Spatial(Box::new(state)), item.clone()],
                    font,
                    &mut source,
                    sw,
                    sh,
                    RasterOptions {
                        scale: scale as f64,
                        scroll: 0.0,
                        profile,
                    },
                );
                let left = (visual.x * scale + pad as f32).floor().clamp(0.0, w as f32) as usize;
                let top = (visual.y * scale + pad as f32).floor().clamp(0.0, h as f32) as usize;
                let right = ((visual.x + visual.width) * scale + pad as f32)
                    .ceil()
                    .clamp(0.0, w as f32) as usize;
                let bottom = ((visual.y + visual.height) * scale + pad as f32)
                    .ceil()
                    .clamp(0.0, h as f32) as usize;
                let target = stack.last_mut().unwrap();
                for y in top..bottom {
                    for x in left..right {
                        let (sx, sy) = (
                            (x as f32 + 0.5 - pad as f32) / scale,
                            (y as f32 + 0.5 - pad as f32) / scale,
                        );
                        if !spatial.contains(sx, sy + item_scroll) {
                            continue;
                        }
                        let Some((u, v)) = matrix.unproject(sx, sy) else {
                            continue;
                        };
                        if object.is_some_and(|r| !contains(r, u, v)) {
                            continue;
                        }
                        let (tx, ty) = (
                            ((u - origin_x) * scale).floor() as i32,
                            ((v - origin_y) * scale).floor() as i32,
                        );
                        if tx < 0 || ty < 0 || tx as usize >= sw || ty as usize >= sh {
                            continue;
                        }
                        let s = source[ty as usize * sw + tx as usize];
                        if s >> 24 != 0 {
                            target.paint(y * w + x, s, Blend::Normal);
                        }
                    }
                }
            }
        }
    }
    let root = &stack[0];
    for y in 0..height {
        for x in 0..width {
            pixels[y * width + x] = root.effective((y + pad) * w + x + pad) & 0xffffff;
        }
    }
}

fn contains(r: Rect, x: f32, y: f32) -> bool {
    x >= r.x && x < r.x + r.width && y >= r.y && y < r.y + r.height
}
fn item_bounds(item: &DisplayItem) -> Option<Rect> {
    Some(match item {
        DisplayItem::Vector { rect, .. } => *rect,
        DisplayItem::Rect { x, y, w, h, .. }
        | DisplayItem::ColorRect { x, y, w, h, .. }
        | DisplayItem::Image { x, y, w, h, .. }
        | DisplayItem::OutlineRect { x, y, w, h, .. } => Rect {
            x: *x,
            y: *y,
            width: *w,
            height: *h,
        },
        DisplayItem::Text {
            x,
            baseline,
            glyphs,
            size,
            ..
        }
        | DisplayItem::ColorText {
            x,
            baseline,
            glyphs,
            size,
            ..
        } => {
            let r = glyphs.ink_bounds(*size, *x, *baseline);
            Rect {
                x: r.x - 2.0,
                y: r.y - 2.0,
                width: r.width + 4.0,
                height: r.height + 4.0,
            }
        }
        DisplayItem::TextDecoration { rect, .. } => Rect {
            height: rect.height * 3.0,
            width: rect.width * 3.0,
            ..*rect
        },
        _ => return None,
    })
}

/// Transparent-edge separable Gaussian convolution in premultiplied RGBA.
/// Kernel is truncated at 3 sigma and normalized once, not at each edge.
pub fn gaussian(pixels: &mut [u32], width: usize, height: usize, sigma: f32) {
    let sigma = sigma.clamp(0.0, MAX_BLUR);
    if sigma < 0.01 || pixels.len() != width * height {
        return;
    }
    let radius = (3.0 * sigma).ceil() as i32;
    let mut kernel: Vec<_> = (-radius..=radius)
        .map(|i| (-(i * i) as f32 / (2.0 * sigma * sigma)).exp())
        .collect();
    let sum: f32 = kernel.iter().sum();
    for k in &mut kernel {
        *k /= sum;
    }
    let mut horizontal = vec![[0.0; 4]; pixels.len()];
    for y in 0..height {
        for x in 0..width {
            let dst = &mut horizontal[y * width + x];
            for (k, &weight) in kernel.iter().enumerate() {
                let sx = x as i32 + k as i32 - radius;
                if sx >= 0 && (sx as usize) < width {
                    let c = unpack(pixels[y * width + sx as usize]);
                    let sample = [c[0] * c[3], c[1] * c[3], c[2] * c[3], c[3]];
                    for (c, d) in dst.iter_mut().enumerate() {
                        *d += sample[c] * weight;
                    }
                }
            }
        }
    }
    for y in 0..height {
        for x in 0..width {
            let mut dst = [0.0; 4];
            for (k, &weight) in kernel.iter().enumerate() {
                let sy = y as i32 + k as i32 - radius;
                if sy >= 0 && (sy as usize) < height {
                    for (c, d) in dst.iter_mut().enumerate() {
                        *d += horizontal[sy as usize * width + x][c] * weight;
                    }
                }
            }
            if dst[3] > 0.0 {
                for c in 0..3 {
                    dst[c] /= dst[3];
                }
            }
            pixels[y * width + x] = pack(dst);
        }
    }
}

pub fn apply_filters(
    pixels: &mut [u32],
    width: usize,
    height: usize,
    scale: f32,
    size: f32,
    current: ResolvedColor,
    filters: &[Filter],
) {
    apply_filters_profile(
        pixels,
        width,
        height,
        scale,
        size,
        current,
        filters,
        ColorProfile::Srgb,
    );
}

#[allow(clippy::too_many_arguments)]
fn apply_filters_profile(
    pixels: &mut [u32],
    width: usize,
    height: usize,
    scale: f32,
    size: f32,
    current: ResolvedColor,
    filters: &[Filter],
    profile: ColorProfile,
) {
    for f in filters {
        match f {
            Filter::Blur(l) => gaussian(
                pixels,
                width,
                height,
                l.resolve(size, 0.0).clamp(0.0, MAX_BLUR) * scale,
            ),
            Filter::DropShadow { x, y, blur, color } => {
                let color = color.resolve(current).unwrap_or(current);
                let (rgb, alpha) = profile.color(color);
                let original = pixels.to_vec();
                let mut shadow = original
                    .iter()
                    .map(|&p| ((p >> 24) * alpha / 255) << 24 | rgb)
                    .collect::<Vec<_>>();
                gaussian(
                    &mut shadow,
                    width,
                    height,
                    blur.resolve(size, 0.0).clamp(0.0, MAX_BLUR) * scale,
                );
                let dx = (x.resolve(size, 0.0) * scale).round() as i32;
                let dy = (y.resolve(size, 0.0) * scale).round() as i32;
                for y in 0..height {
                    for x in 0..width {
                        let (sx, sy) = (x as i64 - dx as i64, y as i64 - dy as i64);
                        let b = if sx >= 0 && sy >= 0 && sx < width as i64 && sy < height as i64 {
                            shadow[sy as usize * width + sx as usize]
                        } else {
                            0
                        };
                        pixels[y * width + x] =
                            composite(b, original[y * width + x], Blend::Normal);
                    }
                }
            }
            _ => {
                for p in pixels.iter_mut() {
                    let mut c = unpack(*p);
                    let convert = profile != ColorProfile::Srgb && !matches!(f, Filter::Opacity(_));
                    if convert {
                        let color = ResolvedColor {
                            space: profile.space(),
                            channels: [c[0] as f64, c[1] as f64, c[2] as f64],
                            alpha: c[3] as f64,
                            missing: 0,
                        }
                        .convert(crate::css::values::ColorSpace::Srgb);
                        c[..3].copy_from_slice(&color.channels.map(|v| v as f32));
                    }
                    let (r, g, b) = (c[0], c[1], c[2]);
                    match f {
                        Filter::Brightness(n) => {
                            for v in &mut c[..3] {
                                *v *= n;
                            }
                        }
                        Filter::Contrast(n) => {
                            for v in &mut c[..3] {
                                *v = (*v - 0.5) * n + 0.5;
                            }
                        }
                        Filter::Invert(n) => {
                            for v in &mut c[..3] {
                                *v = *v * (1.0 - n) + (1.0 - *v) * n;
                            }
                        }
                        Filter::Opacity(n) => c[3] *= n,
                        Filter::Grayscale(n) => {
                            let l = 0.2126 * r + 0.7152 * g + 0.0722 * b;
                            for v in &mut c[..3] {
                                *v = *v * (1.0 - n) + l * n;
                            }
                        }
                        Filter::Sepia(n) => {
                            let sepia = [
                                0.393 * r + 0.769 * g + 0.189 * b,
                                0.349 * r + 0.686 * g + 0.168 * b,
                                0.272 * r + 0.534 * g + 0.131 * b,
                            ];
                            for i in 0..3 {
                                c[i] = c[i] * (1.0 - n) + sepia[i] * n;
                            }
                        }
                        Filter::Saturate(n) => {
                            let l = 0.213 * r + 0.715 * g + 0.072 * b;
                            for v in &mut c[..3] {
                                *v = l + (*v - l) * n;
                            }
                        }
                        Filter::HueRotate(a) => {
                            let (s, k) = (a.sin() as f32, a.cos() as f32);
                            c[0] = (0.213 + 0.787 * k - 0.213 * s) * r
                                + (0.715 - 0.715 * k - 0.715 * s) * g
                                + (0.072 - 0.072 * k + 0.928 * s) * b;
                            c[1] = (0.213 - 0.213 * k + 0.143 * s) * r
                                + (0.715 + 0.285 * k + 0.140 * s) * g
                                + (0.072 - 0.072 * k - 0.283 * s) * b;
                            c[2] = (0.213 - 0.213 * k - 0.787 * s) * r
                                + (0.715 - 0.715 * k + 0.715 * s) * g
                                + (0.072 + 0.928 * k + 0.072 * s) * b;
                        }
                        _ => unreachable!(),
                    }
                    if convert {
                        let color =
                            ResolvedColor::srgb(c[0] as f64, c[1] as f64, c[2] as f64, c[3] as f64)
                                .convert(profile.space());
                        c[..3].copy_from_slice(&color.channels.map(|v| v as f32));
                    }
                    *p = pack(c);
                }
            }
        }
    }
}

fn box_rect(layer: &Layer, k: Keyword) -> Rect {
    match k {
        Keyword::ContentBox => layer.content,
        Keyword::PaddingBox => layer.padding,
        _ => layer.rect,
    }
}
enum MaskSource<'a> {
    Empty,
    Raster(&'a DecodedImage),
    Gradient {
        radial: bool,
        angle: f64,
        stops: Vec<([f32; 4], f32)>,
    },
}

struct PreparedMaskLayer<'a> {
    source: MaskSource<'a>,
    origin: Rect,
    clip: Option<Rect>,
    width: f32,
    height: f32,
    x: f32,
    y: f32,
    repeat: (Repeat, Repeat),
    luminance: bool,
    composite: Composite,
}

struct PreparedMask<'a>(Vec<PreparedMaskLayer<'a>>);

impl<'a> PreparedMask<'a> {
    fn new(layer: &'a Layer) -> Option<Self> {
        let Value::Images(images) = layer.effects.get(Property::MaskImage) else {
            return None;
        };
        if images.iter().all(|i| *i == MaskImage::None) {
            return None;
        }
        let Value::Modes(modes) = layer.effects.get(Property::MaskMode) else {
            unreachable!()
        };
        let Value::Repeats(repeats) = layer.effects.get(Property::MaskRepeat) else {
            unreachable!()
        };
        let Value::Sizes(sizes) = layer.effects.get(Property::MaskSize) else {
            unreachable!()
        };
        let Value::Positions(positions) = layer.effects.get(Property::MaskPosition) else {
            unreachable!()
        };
        let Value::Boxes(origins) = layer.effects.get(Property::MaskOrigin) else {
            unreachable!()
        };
        let Value::Boxes(clips) = layer.effects.get(Property::MaskClip) else {
            unreachable!()
        };
        let Value::Composites(composites) = layer.effects.get(Property::MaskComposite) else {
            unreachable!()
        };
        let mut layers = Vec::with_capacity(images.len());
        for (i, image) in images.iter().enumerate() {
            let origin = box_rect(layer, origins[i % origins.len()]);
            let clipping = clips[i % clips.len()];
            let decoded = if let MaskImage::Url(u) = image {
                layer.images.get(u)
            } else {
                None
            };
            let natural = decoded.map_or((origin.width, origin.height), |i| {
                (i.width() as f32, i.height() as f32)
            });
            let (mut w, mut h) = match &sizes[i % sizes.len()] {
                MaskSize::Auto => natural,
                MaskSize::Contain | MaskSize::Cover => {
                    let f = if sizes[i % sizes.len()] == MaskSize::Contain {
                        (origin.width / natural.0).min(origin.height / natural.1)
                    } else {
                        (origin.width / natural.0).max(origin.height / natural.1)
                    };
                    (natural.0 * f, natural.1 * f)
                }
                MaskSize::Size(w, h) => {
                    let w = w.as_ref().map(|l| l.resolve(layer.size, origin.width));
                    let h = h.as_ref().map(|l| l.resolve(layer.size, origin.height));
                    match (w, h) {
                        (Some(w), Some(h)) => (w, h),
                        (Some(w), None) => (
                            w,
                            if decoded.is_some() {
                                w * natural.1 / natural.0
                            } else {
                                origin.height
                            },
                        ),
                        (None, Some(h)) => (
                            if decoded.is_some() {
                                h * natural.0 / natural.1
                            } else {
                                origin.width
                            },
                            h,
                        ),
                        _ => natural,
                    }
                }
            };
            let rep = repeats[i % repeats.len()];
            if rep.0 == Repeat::Round && w > 0.0 {
                w = origin.width / (origin.width / w).round().max(1.0);
            }
            if rep.1 == Repeat::Round && h > 0.0 {
                h = origin.height / (origin.height / h).round().max(1.0);
            }
            let p = &positions[i % positions.len()];
            let offset = |a: &crate::style::ObjectAxis, free: f32| {
                let o = a.offset.resolve(layer.size, free);
                if a.from_end { free - o } else { o }
            };
            let ox = origin.x + offset(&p.x, origin.width - w);
            let oy = origin.y + offset(&p.y, origin.height - h);
            let source = match image {
                MaskImage::None => MaskSource::Empty,
                MaskImage::Url(_) => {
                    decoded.map_or(MaskSource::Empty, |image| MaskSource::Raster(image))
                }
                MaskImage::Gradient(g) if w > 0.0 && h > 0.0 && w.is_finite() && h.is_finite() => {
                    MaskSource::Gradient {
                        radial: g.radial,
                        angle: g.angle,
                        stops: gradient_stops(g, w, h, layer),
                    }
                }
                MaskImage::Gradient(_) => MaskSource::Empty,
            };
            layers.push(PreparedMaskLayer {
                source,
                origin,
                clip: (clipping != Keyword::NoClip).then(|| box_rect(layer, clipping)),
                width: w,
                height: h,
                x: ox,
                y: oy,
                repeat: rep,
                luminance: modes[i % modes.len()] == MaskMode::Luminance,
                composite: composites[i % composites.len()],
            });
        }
        Some(Self(layers))
    }

    fn alpha(&self, x: f32, y: f32) -> f32 {
        let mut result = 0.0;
        for (i, layer) in self.0.iter().enumerate().rev() {
            let mut alpha = 0.0;
            if layer.clip.is_none_or(|r| contains(r, x, y))
                && let (Some(u), Some(v)) = (
                    mask_tile(
                        x,
                        layer.x,
                        layer.width,
                        layer.origin.x,
                        layer.origin.width,
                        layer.repeat.0,
                    ),
                    mask_tile(
                        y,
                        layer.y,
                        layer.height,
                        layer.origin.y,
                        layer.origin.height,
                        layer.repeat.1,
                    ),
                )
            {
                let rgba = match &layer.source {
                    MaskSource::Empty => [0.0; 4],
                    MaskSource::Raster(image) => {
                        let sx = (u / layer.width * image.width() as f32).floor() as usize;
                        let sy = (v / layer.height * image.height() as f32).floor() as usize;
                        let idx = (sy.min(image.height() as usize - 1) * image.width() as usize
                            + sx.min(image.width() as usize - 1))
                            * 4;
                        std::array::from_fn(|c| image.rgba()[idx + c] as f32 / 255.0)
                    }
                    MaskSource::Gradient {
                        radial,
                        angle,
                        stops,
                    } => gradient(
                        gradient_geometry(*radial, *angle, u, v, layer.width, layer.height).0,
                        stops,
                    ),
                };
                alpha = rgba[3]
                    * if layer.luminance {
                        0.2126 * rgba[0] + 0.7152 * rgba[1] + 0.0722 * rgba[2]
                    } else {
                        1.0
                    };
            }
            if i == self.0.len() - 1 {
                result = alpha;
                continue;
            }
            result = match layer.composite {
                Composite::Add => alpha + result * (1.0 - alpha),
                Composite::Subtract => alpha * (1.0 - result),
                Composite::Intersect => alpha * result,
                Composite::Exclude => alpha * (1.0 - result) + result * (1.0 - alpha),
            };
        }
        result
    }
}

fn mask_tile(
    v: f32,
    start: f32,
    size: f32,
    area_start: f32,
    area_size: f32,
    repeat: Repeat,
) -> Option<f32> {
    if size <= 0.0 || !size.is_finite() {
        return None;
    }
    let local = v - start;
    match repeat {
        Repeat::Repeat | Repeat::Round => Some(local.rem_euclid(size)),
        Repeat::NoRepeat => (local >= 0.0 && local < size).then_some(local),
        Repeat::Space => {
            let n = (area_size / size).floor();
            if n < 2.0 {
                (local >= 0.0 && local < size).then_some(local)
            } else {
                let step = (area_size - size) / (n - 1.0);
                let q = (v - area_start).rem_euclid(step);
                (v >= area_start && v < area_start + area_size && q < size).then_some(q)
            }
        }
    }
}

fn gradient_geometry(radial: bool, angle: f64, x: f32, y: f32, w: f32, h: f32) -> (f32, f32) {
    if radial {
        (
            (((x - w / 2.0) / (w / 2.0)).powi(2) + ((y - h / 2.0) / (h / 2.0)).powi(2)).sqrt()
                / 2.0f32.sqrt(),
            (w * w + h * h).sqrt() / 2.0,
        )
    } else {
        let (dx, dy) = (angle.sin() as f32, -angle.cos() as f32);
        let length = dx.abs() * w + dy.abs() * h;
        (
            ((x - w / 2.0) * dx + (y - h / 2.0) * dy) / length + 0.5,
            length,
        )
    }
}

fn gradient_stops(g: &effects::Gradient, w: f32, h: f32, layer: &Layer) -> Vec<([f32; 4], f32)> {
    let length = gradient_geometry(g.radial, g.angle, 0.0, 0.0, w, h).1;
    let mut stops = g
        .stops
        .iter()
        .map(|(c, p)| {
            (
                c.resolve(layer.color).unwrap_or(ResolvedColor::TRANSPARENT),
                p.as_ref().map(|l| l.resolve(layer.size, length) / length),
            )
        })
        .collect::<Vec<_>>();
    if stops[0].1.is_none() {
        stops[0].1 = Some(0.0);
    }
    let last = stops.len() - 1;
    if stops[last].1.is_none() {
        stops[last].1 = Some(1.0);
    }
    let mut previous = stops[0].1.unwrap();
    for stop in &mut stops {
        if let Some(p) = &mut stop.1 {
            *p = p.max(previous);
            previous = *p;
        }
    }
    let mut i = 0;
    while i < last {
        let mut j = i + 1;
        while stops[j].1.is_none() {
            j += 1;
        }
        let (a, b) = (stops[i].1.unwrap(), stops[j].1.unwrap());
        for (k, stop) in stops.iter_mut().enumerate().take(j).skip(i + 1) {
            stop.1 = Some(a + (b - a) * (k - i) as f32 / (j - i) as f32);
        }
        i = j;
    }
    stops
        .into_iter()
        .map(|(c, p)| {
            let (rgb, a) = c.to_srgb8();
            (unpack((a << 24) | rgb), p.unwrap())
        })
        .collect()
}

fn gradient(t: f32, stops: &[([f32; 4], f32)]) -> [f32; 4] {
    if t < stops[0].1 {
        return stops[0].0;
    }
    for pair in stops.windows(2) {
        let (a, b) = (pair[0].1, pair[1].1);
        if t >= a && t < b {
            let f = (t - a) / (b - a);
            let (a, b) = (pair[0].0, pair[1].0);
            let alpha = a[3] * (1.0 - f) + b[3] * f;
            if alpha == 0.0 {
                return [0.0; 4];
            }
            return [
                (a[0] * a[3] * (1.0 - f) + b[0] * b[3] * f) / alpha,
                (a[1] * a[3] * (1.0 - f) + b[1] * b[3] * f) / alpha,
                (a[2] * a[3] * (1.0 - f) + b[2] * b[3] * f) / alpha,
                alpha,
            ];
        }
    }
    stops.last().unwrap().0
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn transparent_gaussian_has_real_kernel_and_color_not_white_edges() {
        let mut p = vec![0; 49];
        p[24] = 0xffff0000;
        gaussian(&mut p, 7, 7, 1.0);
        assert_eq!(p[24] >> 24, 41);
        assert_eq!(p[25] >> 24, 25);
        assert_eq!(p[26] >> 24, 5);
        assert_eq!(p[24] & 0xffffff, 0xff0000);
        assert_eq!(p[25] & 0xffffff, 0xff0000);
        assert!((245..=265).contains(&p.iter().map(|p| p >> 24).sum::<u32>()));
    }
    #[test]
    fn all_separable_blends_use_independent_numeric_vectors() {
        let b = [0.2, 0.6, 0.8];
        let s = [0.4, 0.3, 0.9];
        let expected = [
            (Blend::Normal, [0.4, 0.3, 0.9]),
            (Blend::Multiply, [0.08, 0.18, 0.72]),
            (Blend::Screen, [0.52, 0.72, 0.98]),
            (Blend::Overlay, [0.16, 0.44, 0.96]),
            (Blend::Darken, [0.2, 0.3, 0.8]),
            (Blend::Lighten, [0.4, 0.6, 0.9]),
            (Blend::ColorDodge, [1.0 / 3.0, 6.0 / 7.0, 1.0]),
            (Blend::ColorBurn, [0.0, 0.0, 7.0 / 9.0]),
            (Blend::HardLight, [0.16, 0.36, 0.96]),
            (Blend::SoftLight, [0.168, 0.504, 0.87554175]),
            (Blend::Difference, [0.2, 0.3, 0.1]),
            (Blend::Exclusion, [0.44, 0.54, 0.26]),
        ];
        for (mode, want) in expected {
            for (a, b) in blend_rgb(b, s, mode).into_iter().zip(want) {
                assert!((a - b).abs() < 1e-5, "{mode:?}: {a} != {b}");
            }
        }
        assert_eq!(composite(0, 0x80ff0000, Blend::Multiply), 0x80ff0000);
        assert_eq!(composite(0xff00ff00, 0, Blend::Color), 0xff00ff00);
    }

    #[test]
    fn nonseparable_blend_vectors_and_premultiplied_alpha_are_independent() {
        let b = [0.2, 0.6, 0.8];
        let s = [0.4, 0.3, 0.7];
        for (mode, want) in [
            (Blend::Hue, [0.541, 0.391, 0.991]),
            (Blend::Saturation, [0.30066666, 0.56733334, 0.70066667]),
            (Blend::Color, [0.528, 0.428, 0.828]),
            (Blend::Luminosity, [0.072, 0.472, 0.672]),
        ] {
            for (a, b) in blend_rgb(b, s, mode).into_iter().zip(want) {
                assert!((a - b).abs() < 1e-5, "{mode:?}: {a} != {b}");
            }
        }
        assert_eq!(
            composite(0x800000ff, 0x80ff0000, Blend::Multiply),
            0xc0550055
        );
    }

    #[test]
    fn all_color_filters_leave_transparency_and_apply_constant_pixel_matrices() {
        let current = ResolvedColor::BLACK;
        for (filter, want) in [
            (Filter::Brightness(0.5), 0x80402010),
            (Filter::Contrast(0.0), 0x80808080),
            (Filter::Invert(1.0), 0x807fbfdf),
            (Filter::Opacity(0.5), 0x40804020),
            (Filter::Grayscale(1.0), 0x804b4b4b),
            (Filter::Sepia(1.0), 0x806a5e49),
            (Filter::Saturate(0.0), 0x804b4b4b),
        ] {
            let mut p = [0x80804020];
            apply_filters(
                &mut p,
                1,
                1,
                1.0,
                16.0,
                current,
                std::slice::from_ref(&filter),
            );
            assert_eq!(p[0], want, "{filter:?}");
        }
        let mut p = [0x00ff0000];
        apply_filters(&mut p, 1, 1, 1.0, 16.0, current, &[Filter::Invert(1.0)]);
        assert_eq!(p[0] >> 24, 0);
    }
}
